<script setup lang="ts">
import type { ScientificSnapshot as AtomisticSnapshot } from "../../../../../packages/contracts/src/atomistic-dynamics.js";
import { openAtomicView, openAtomicComparison, openAtomicTrajectory } from "../utils/atomic-viewer";
import { computed,ref,watch } from "vue";
const props=defineProps<{run:AtomisticSnapshot;locale:"zh"|"en"}>();
const t=(zh:string,en:string)=>props.locale==="zh"?zh:en;
const structureArtifact=computed(()=>props.run.artifacts.find(a=>a.type==="atomic_structure"&&!a.partial&&(!props.run.relaxation||a.relativePath.endsWith('/final.json'))));
const trajectoryArtifact=computed(()=>props.run.artifacts.find(a=>a.id===props.run.md?.trajectoryArtifactId));
const error=ref("");
const components=ref<import('../../../../../packages/contracts/src/potential-physics.js').CompositionResult|null>(null);
watch(()=>[props.run.job.id,props.run.job.status],async()=>{components.value=null;if(props.run.job.status==='completed'&&props.run.plan.potentialId==='mace-mp-0b3-medium-d3-bj-pbe-si'){try{components.value=await window.materialsx.getAtomicComposition(props.run.job.projectId,props.run.job.id);}catch(e){error.value=String(e);}}},{immediate:true});
async function receipt(){try{await window.materialsx.exportScientificReceipt(props.run.job.projectId,props.run.job.id);}catch(e){error.value=t('导出复现回执失败：','Reproduction receipt export failed: ')+String(e);}}
async function reveal(){try{await window.materialsx.revealArtifact(props.run.outputDirectory);}catch(e){error.value=String(e);}}
</script>
<template><div v-if="trajectoryArtifact" class="atomic-artifact-card" data-testid="atomic-trajectory-card"><div><strong>{{t('分子动力学轨迹','Molecular dynamics trajectory')}}</strong><p>{{run.plan.potentialId}} · {{run.md?.options.ensemble.toUpperCase()}} · {{trajectoryArtifact.frames}} {{t('帧','frames')}}</p><small>{{trajectoryArtifact.partial?t('任务未完成 · 部分有效轨迹','Incomplete task · Partial valid trajectory'):t('已完成请求步数 · 需科学复核','Requested steps completed · Needs review')}}</small></div><button class="secondary-button" data-testid="open-md-trajectory" @click="openAtomicTrajectory({projectId:run.job.projectId,runId:run.job.id})">{{t('播放 3D 轨迹与诊断','Play 3D trajectory and diagnostics')}}</button><button v-if="run.job.status==='completed'" class="secondary-button" data-testid="export-reproduction-receipt" @click="receipt">{{t('导出复现回执','Export reproduction receipt')}}</button><button class="secondary-button" @click="reveal">{{t('查看产物','Reveal artifacts')}}</button><p v-if="error" role="alert">{{error}}</p></div><div v-if="!run.md&&structureArtifact&&run.job.status==='completed'" class="atomic-artifact-card" data-testid="atomic-artifact-card"><div><strong>{{t('原子计算产物','Atomic calculation artifacts')}}</strong><p>{{run.plan.potentialId}} · {{run.structure.atoms.length}} {{t('原子','atoms')}} · {{run.result?.energyEv.toFixed(8)}} eV</p><p v-if="run.plan.potentialId==='ani-2x-ensemble'">{{t('中性单重态 · 孤立分子 · 无显式长程静电 · 应力不适用','Neutral singlet · Isolated molecule · No explicit long-range electrostatics · Stress not applicable')}}</p><small>{{run.relaxation?(run.relaxation.summary?.stopReason==='converged'?t('优化已收敛 · 需科学复核','Relaxation converged · Needs review'):t('优化未收敛 · 需科学复核','Relaxation not converged · Needs review')):t('单点计算 · 需科学复核','Single point · Needs scientific review')}}</small></div><button class="secondary-button" @click="openAtomicView({kind:'artifact',projectId:run.job.projectId,runId:run.job.id,artifactId:structureArtifact.id})">{{t('查看 3D 与产物','View 3D and artifacts')}}</button><button v-if="run.relaxation?.summary" class="secondary-button" @click="openAtomicComparison({projectId:run.job.projectId,runId:run.job.id})">{{t('优化前后对比','Compare before / after')}}</button><button class="secondary-button" data-testid="export-reproduction-receipt" @click="receipt">{{t('导出复现回执','Export reproduction receipt')}}</button><div v-if="components" class="composition" data-testid="composition-components"><strong>{{t('同一结构 · 组合势分项','Same structure · Composition components')}}</strong><table><thead><tr><th>{{t('分项','Component')}}</th><th>E (eV)</th><th>Fmax (eV/Å)</th></tr></thead><tbody><tr v-for="key in (['baseline','correction','total'] as const)" :key="key"><td>{{key==='baseline'?t('MACE 基线','MACE baseline'):key==='correction'?'D3(BJ) · PBE':t('总量','Total')}}</td><td>{{components[key].energyEv.toFixed(10)}}</td><td>{{Math.max(...components[key].forcesEvPerAngstrom.map(f=>Math.hypot(...f))).toFixed(8)}}</td></tr></tbody></table><p>{{t('能量、力、应力逐项相加；Fmax 由各自合力计算，不直接相加。','Energy, forces and stress add componentwise; Fmax is computed from each force vector, not added.')}}</p><p>{{t('纯硅 · 两体 D3 · 固定晶胞 · 截断 10/5 Å · 无 ATM / 静电 · 需科学复核','Pure Si · two-body D3 · fixed cell · cutoffs 10/5 Å · no ATM / electrostatics · needs review')}}</p><details><summary>{{t('分项应力 eV/Å³（拉伸为正）','Component stress eV/Å³ (positive tension)')}}</summary><p v-for="key in (['baseline','correction','total'] as const)" :key="key">{{key}} · {{components[key].stress.map(x=>x.toExponential(5)).join(' / ')}}</p><small>xx / yy / zz / yz / xz / xy</small></details></div><details><summary>{{t('已登记真实文件','Registered real files')}} · {{run.artifacts.length}}</summary><p v-for="a in run.artifacts" :key="a.id">{{a.type}} · {{a.bytes}} bytes<br><code>{{a.id}}</code><br><small>SHA256 {{a.sha256}}</small></p><button class="secondary-button" @click="reveal">{{t('打开产物文件夹','Reveal artifact folder')}}</button></details><p v-if="error" role="alert">{{error}}</p></div></template>
<style scoped>.atomic-artifact-card{display:flex;gap:16px;flex-wrap:wrap;align-items:center;justify-content:space-between;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--panel-2);margin:12px 0;color:var(--text)}p{font-size:13px;line-height:1.65;margin:6px 0}small{color:var(--muted);font-size:12px}details{width:100%;font-size:12px;overflow-wrap:anywhere}.composition{width:100%}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:8px;text-align:left;border-bottom:1px solid var(--line)}summary{cursor:pointer;color:var(--muted)}code{font-size:11px}</style>
